/// <summary>
/// Data contract class as a response for service <c>METPickListCancelService</c>
/// </summary>
[DataContractAttribute]
class METPickListCancelResponseContract extends METBaseResponseContract
{
}

Method.Source:
    /// <summary>
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_cancelResult">Result of the cancellation</param>
    /// <param name = "_cancelMessage">Message Result</param>
    /// <returns>new contract</returns>
    public static METPickListCancelResponseContract newFromParameters(METProcessingStatus _cancelResult, Description255 _cancelMessage)
    {
        METPickListCancelResponseContract PickListCancelResponse = new METPickListCancelResponseContract();

        PickListCancelResponse.parmCancelResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_cancelResult)));
        PickListCancelResponse.parmCancelMessage(_cancelMessage);

        return PickListCancelResponse;
    }
